      "ruleSummary": "This unit covers good/well, fast/hard/late, and hardly. Good is an adjective, well is the adverb: 'Your English is good' but 'You speak English well'; well is also used before past participles (well-known, well-paid) and as an adjective meaning 'in good health' ('I'm very well, thanks.'). Fast, hard and late are both adjectives and adverbs with the same form: 'a fast runner' / 'run fast'; 'hard work' / 'work hard' (not 'work hardly'); 'Sorry I'm late' / 'I got up late'. Lately means 'recently'. Hardly means 'very little, almost not' and goes before the verb: 'We hardly know each other' (not 'We know each other hardly'); 'I can hardly do something' means it's almost impossible. Hardly is used with any/anybody/anyone/anything/anywhere ('hardly any', 'hardly anybody') and hardly ever means 'almost never'. A correct student sentence should use well (not good) to describe how an action is done, hard (not hardly) to mean 'a lot of effort', and hardly correctly positioned before the verb to mean 'very little'."
