      "instructionsEn": "Write 2-3 English sentences using quite, pretty, rather or fairly to describe something in your own words (the weather, a film, someone you know ...). Use rather + adjective for at least one sentence, e.g. 'The film was rather boring.'.",
      "ruleSummary": "This unit covers quite, pretty, rather and fairly, all normally meaning 'less than very, more than a little'. Quite and pretty are similar ('quite famous'/'pretty famous'); pretty is informal/spoken. Quite goes before a/an ('quite an old house', not 'a quite old house'); only quite (not pretty) is used in 'quite a surprise' (noun without adjective), 'quite a lot (of)', and before verbs like like/enjoy ('I quite like tennis'). Rather is similar but often used for negative ideas ('rather cloudy', 'rather shy'); with positive ideas it means 'unusually/surprisingly' ('rather good'). Fairly is weaker than the others: 'fairly good' is not very good and could be better. Quite also means 'completely' with certain adjectives (sure, right, true, different, impossible etc.) and some verbs ('quite agree'); not quite means 'not completely'. A correct student sentence should put quite/pretty/rather/fairly directly before the adjective (quite before a/an + adjective + noun, e.g. 'quite a good film', not 'a quite good film')."
