        { "context": "I expected my friends to arrive at about 4 o'clock. In fact they arrived at 2.30.", "prompt": "My friends ___ I expected.", "answer": "arrived earlier than" },
        { "context": "There is always a lot of traffic here, but today the traffic is really bad.", "prompt": "The traffic today ___ usual.", "answer": "is worse than" }
