            { "kind": "text", "text": "A few superlative forms are irregular:", "vi": "Một số dạng so sánh nhất là bất quy tắc:" },
            { "kind": "table", "table": { "variant": "list", "rows": [["good", "best"], ["bad", "worst"], ["far", "furthest or farthest"]] } },
            { "kind": "text", "text": "The rules are the same as those for the comparative - see Unit 105.", "vi": "Các quy tắc này giống với dạng so sánh hơn - xem Unit 105." }
