      "instructions": "Hoàn thành mỗi câu bằng dạng so sánh nhất + giới từ (of hoặc in), dựa trên tính từ gạch chân.",
      "instructionsEn": "Complete the sentences using a superlative + a preposition (of or in), based on the underlined adjective.",
