              { "en": "I sent him an invitation weeks ago and he **still hasn't replied**.", "note": "he should have replied before now", "vi": "Tôi đã gửi thiệp mời cho anh ấy mấy tuần trước mà anh ấy vẫn chưa trả lời." }
